"""Three isolated visual prototypes. No application or reward service is modified."""
from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'reports/visual-direction-v2'
OUT.mkdir(parents=True, exist_ok=True)

def encoded(file):
    return base64.b64encode((ROOT / file).read_bytes()).decode()

FONT = ''
for weight, folder in [(400,'400Regular'),(600,'600SemiBold'),(700,'700Bold')]:
    data = encoded(f'node_modules/@expo-google-fonts/ibm-plex-sans-arabic/{folder}/IBMPlexSansArabic_{folder}.ttf')
    FONT += f"@font-face{{font-family:Plex;src:url(data:font/ttf;base64,{data});font-weight:{weight};font-display:swap}}"
MONO = encoded('node_modules/@expo-google-fonts/jetbrains-mono/400Regular/JetBrainsMono_400Regular.ttf')
FONT += f"@font-face{{font-family:Mono;src:url(data:font/ttf;base64,{MONO});font-weight:400;font-display:swap}}"
LOGO = encoded('assets/kodax-light-trans.png')

def icon(name, size=22):
    paths = {
      'code':'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-2-15-4 18"/>',
      'branch':'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M6 9v6a3 3 0 0 0 3 3h6M9 6h6v6"/>',
      'check':'<path d="m5 12 4 4L19 6"/>',
      'book':'<path d="M12 6v15M3 4h4c3 0 5 2 5 2s2-2 5-2h4v15h-4c-3 0-5 2-5 2s-2-2-5-2H3Z"/>',
      'lock':'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
      'arrow':'<path d="M20 12H4m6-6-6 6 6 6"/>',
      'play':'<path d="m8 4 12 8-12 8Z"/>',
      'home':'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3Z"/>',
      'medal':'<path d="m7 3 5 6 5-6m-5 6 7 5-3 8H8l-3-8Z"/><path d="m9 15 2 2 4-4"/>',
      'message':'<path d="M4 4h16v12H9l-5 4Zm4 4h8m-8 4h5"/>',
      'user':'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
      'download':'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
      'close':'<path d="m6 6 12 12M6 18 18 6"/>',
      'coins':'<ellipse cx="12" cy="6" rx="8" ry="3"/><path d="M4 6v12c0 4 16 4 16 0V6M4 12c0 4 16 4 16 0"/>',
      'terminal':'<rect x="2" y="3" width="20" height="18" rx="3"/><path d="m6 8 4 4-4 4m7 0h5"/>',
      'grid':'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
      'layers':'<path d="m12 2 10 6-10 6L2 8Zm-10 12 10 6 10-6M2 13l10 6 10-6"/>',
    }
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'

def brand():
    return f'<span class="brand" aria-label="Kodax"><img src="data:image/png;base64,{LOGO}" alt="شعار Kodax الأصلي"></span>'

def seal(symbol='branch', earned=False, small=False):
    return f'<span class="seal {"earned" if earned else "pending"} {"small" if small else ""}"><span class="seal-face">{icon(symbol,40 if not small else 28)}</span><span class="seal-foot">{icon("check",13) if earned else "&lt;/&gt;"}</span></span>'

def node(n, state='next', symbol=None):
    return f'<span class="node {state}">{icon(symbol,20) if symbol else n}{"<i></i>" if state=="current" else ""}</span>'

def review(page):
    return '<div class="review"><span>معاينة اتجاه 02 <small>· بيانات اختبار، دون حفظ</small></span><nav aria-label="معاينات التصميم">'+''.join(f'<a {"aria-current=page" if key==page else ""} href="kodax-{key}-v2.html">{label}</a>' for key,label in [('welcome','البداية'),('learn','التعلّم'),('rewards','المكافآت')])+'</nav></div>'

def sidebar(page):
    items=[('home','الرئيسية','home'),('learn','تعلّم','book'),('community','المجتمع','code'),('ai','المساعد','message'),('rewards','المكافآت','medal'),('profile','حسابي','user')]
    return '<aside class="sidebar">'+brand()+'<nav aria-label="التنقل">'+''.join(f'<a class="{"selected" if k==page else ""}" href="kodax-{k}-v2.html" '+('' if k in ['learn','rewards'] else 'data-preview="صفحة ضمن مرحلة التعميم التالية"')+f'>{icon(sym)}<span>{label}</span></a>' for k,label,sym in items)+'</nav><div class="side-bottom"><span class="avatar">س</span><div><b class="identity">سارة الكبيسي</b><small>حساب اختبار محلي</small></div></div></aside>'

def mobile_nav(page):
    return '<nav class="mobile-nav" aria-label="التنقل">'+''.join(f'<a class="{"selected" if k==page else ""}" href="kodax-{k}-v2.html" '+('' if k in ['learn','rewards'] else 'data-preview="صفحة ضمن مرحلة التعميم التالية"')+f'>{icon(sym,21)}<span>{label}</span></a>' for k,label,sym in [('home','الرئيسية','home'),('learn','تعلّم','book'),('community','المجتمع','code'),('rewards','المكافآت','medal'),('profile','حسابي','user')])+'</nav>'

