def rewards():
    stamp=''.join(f'<span class="slot {"ok" if n<4 else ""}">{icon("check",15) if n<4 else "5"}</span>' for n in range(5))
    badges=[('play','الضربة الأولى',True,'أول تحدٍّ'),('book','الخطوة الأولى',True,'أول درس'),('code','أول نقطة',True,'أول XP'),('branch','البداية',False,'4 من 5 تحديات'),('book','متعلم متحمس',False,'6 من 10 دروس'),('medal','خريج الدورة',False,'أكمل دورة واحدة')]
    collection=''.join(f'<button class="badge-item {"" if earned else "upcoming"}" data-badge="{label}" data-earned="{str(earned).lower()}" data-criterion="{criterion}">{seal(symbol,earned,True)}<b>{label}</b><small>{"مكتسبة" if earned else criterion}</small></button>' for symbol,label,earned,criterion in badges)
    days=''.join(f'<div class="day {"claimed" if i==0 else "next" if i==1 else ""}"><span>اليوم {i+1}</span><b>{v}</b><span>{"مستلمة ✓" if i==0 else "باجر" if i==1 else "كوين"}</span></div>' for i,v in enumerate([5,10,15,20,25,30,50]))
    return f'''<div class="shell">{sidebar('rewards')}<main class="main"><header class="page-head spread"><div><h1>المكافآت</h1><p>إنجازك القريب، واللي جمعته بطريقك.</p></div><button class="btn ghost" data-preview="سجل الحركات الحالي محفوظ كما هو">{icon('coins')}<span>السجل</span></button></header><section class="reward-top"><div class="next-achievement">{seal('branch')}<div class="achievement-copy"><span class="eyebrow gold">الشارة القادمة</span><h2>البداية</h2><p>أكمل 5 تحديات. باقي تحدّي واحد.</p><div class="five-stamps" aria-label="4 من 5 تحديات مكتملة">{stamp}</div><a class="btn gold-btn" href="kodax-learn-v2.html#challenges">حلّ التحدي التالي {icon('arrow',17)}</a></div></div><aside class="passport"><div class="identity-row"><span class="avatar">س</span><div><b class="identity">سارة الكبيسي</b><p>بطاقة تقدّمك</p></div></div><div class="passport-level"><span class="passport-number">3</span><div><strong>المستوى الحالي</strong><p>440 XP للمستوى الرابع</p></div></div><div class="xp-block"><div class="xp-line" aria-label="1160 من 1600 XP"><i></i></div><div class="xp-meta"><span>1,160 XP</span><span>1,600 XP</span></div></div></aside></section><section><div class="collection-title spread"><div><h2>شاراتك</h2><p class="muted">المكتسبة مختومة، والقادمة تحتفظ بشكلها وشرطها.</p></div><button class="btn ghost" style="font-size:12px" data-all-badges>عرض الكل {icon('arrow',16)}</button></div><div class="badge-collection">{collection}</div></section><div class="rewards-lower"><section><div class="daily-head spread"><div><h3>المكافأة اليومية</h3><p>استلمت مكافأة اليوم. الجاية: 10 كوين باجر.</p></div><span class="tag done">{icon('check',13)} مستلمة</span></div><div class="daily-track">{days}</div><p class="daily-summary">التسلسل والمبالغ من نظام المكافآت الحالي.</p><div class="goals-list"><article class="goal"><span class="goal-icon">{icon('check',19)}</span><div><h3>هدف اليوم محقّق</h3><p>أنجزت 10 دروس أو تحديات · هدفك 2 باليوم</p></div></article><article class="goal"><span class="goal-icon" style="background:#252033;color:#cab5fa">{icon('book',19)}</span><div><h3>يوم واحد لهدف الأسبوع</h3><p>4 أيام تعلّم من الهدف 5 · سلسلتك 4 أيام</p></div></article></div></section><aside class="wallet"><div class="wallet-head">{icon('coins',27)}<div><small>رصيدك الحالي</small><div class="wallet-balance">58 <small>كوين</small></div></div></div><p>تفتح دورة مبكرًا، تجمّد السلسلة أو تزيد طلبات المساعد.</p><div class="wallet-row"><span>تحدٍّ سهل</span><strong>5 كوين</strong></div><div class="wallet-row"><span>تحدٍّ متوسط</span><strong>10 كوين</strong></div><div class="wallet-row"><span>تحدٍّ صعب</span><strong>15 كوين</strong></div><button class="btn" data-preview="اختصارات الكوينات وأسعارها تبقى ضمن الأنظمة الحالية">شوف استخدامات الكوينات {icon('arrow',16)}</button></aside></div></main>{mobile_nav('rewards')}</div>'''

DIALOG = f'''<dialog id="detail-dialog"><div class="dialog-head"><h2 id="dialog-title">التفاصيل</h2><button class="icon-button" id="close-dialog" aria-label="إغلاق">{icon('close')}</button></div><div id="dialog-content"></div></dialog><div class="toast" role="status" id="toast"></div>'''

JS = r'''
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let toastTimer;
function notice(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
$$('[data-preview]').forEach(e=>e.addEventListener('click',event=>{event.preventDefault();notice(e.dataset.preview)}));
function dialog(title,content){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;$('#detail-dialog').showModal()}
$('#close-dialog').onclick=()=>$('#detail-dialog').close();
$('#detail-dialog').onclick=e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}};
$$('[data-course]').forEach(e=>e.onclick=()=>dialog(e.dataset.course,'<p>المسار يعرض إكمال الدروس وإتاحة الدورة من بيانات التطبيق الحالية.</p><p class="dialog-note">هذه معاينة بصرية؛ شروط الفتح والمحتوى لم تتغيّر.</p>'));
$$('[data-lesson]').forEach(e=>e.onclick=()=>dialog('الشروط if/else','<span class="eyebrow">معاينة تركيز الدرس</span><p>الشرط يحدد أي جزء من البرنامج يتنفذ.</p><div class="demo-code"><div class="file-label">conditions.py</div><div class="code-lines"><span class="kw">if</span> score &gt;= <span class="num">5</span>:<br>    print(<span class="str">"ناجح"</span>)</div></div><p class="dialog-note">موضع الإنجاز يظهر بعد الإكمال الفعلي في التطبيق. هذه المعاينة لا تحفظ تقدمًا ولا تمنح XP.</p>'));
$$('[data-badge]').forEach(e=>e.onclick=()=>dialog(e.dataset.badge,e.querySelector('.seal').outerHTML+'<div class="badge-dialog-meta"><span class="tag '+(e.dataset.earned==='true'?'done':'gone')+'">'+(e.dataset.earned==='true'?'مكتسبة في بيانات الاختبار':'لم تُكتسب بعد')+'</span></div><p style="text-align:center;margin-top:15px">'+e.dataset.criterion+'</p><p class="dialog-note">اسم الشارة وشرطها من التعريفات الموجودة. لا مكافأة جديدة في المعاينة.</p>'));
if($('[data-all-badges]'))$('[data-all-badges]').onclick=()=>dialog('الشارات', '<p>معاينة من الفئات الموجودة: الدروس، التحديات، الخبرة والسلسلة.</p><div class="badge-collection" style="grid-template-columns:repeat(3,minmax(0,1fr));margin-top:20px">'+$('.badge-collection').innerHTML+'</div><p class="dialog-note">القائمة الكاملة ستستخدم هذه اللغة البصرية مع شروط الشارات الحالية.</p>');
if($('#run-demo')){
  let op='>=';
  function reset(){ $('#demo-output').className='demo-result';$('#demo-output').innerHTML='<span>&gt;_</span><span>الناتج يظهر هنا بعد التشغيل</span>';$('#demo-earned').classList.remove('visible');$('.demo-run').classList.remove('finished');$('#run-demo').innerHTML='<span>▷</span> شغّل المثال';$('#demo-hint').textContent='تغيير علامة واحدة يغيّر مسار البرنامج.';$$('.demo-step .node').forEach((n,i)=>{n.className='node '+(i===0?'current':'next');n.textContent=i+1;if(i===0)n.innerHTML='1<i></i>'}) }
  $$('[data-op]').forEach(e=>e.onclick=()=>{op=e.dataset.op;$$('[data-op]').forEach(b=>{b.classList.toggle('active',b===e);b.setAttribute('aria-pressed',b===e)});$('#operator').textContent=op;reset()});
  $('#run-demo').onclick=()=>{const correct=op==='>=';$('#demo-output').className='demo-result '+(correct?'success':'error');$('#demo-output').innerHTML='<span>&gt;_</span><span dir="rtl">'+(correct?'ناجح':'حاول مرة ثانية')+'</span>';$('#demo-hint').textContent=correct?'8 أكبر من أو تساوي 5، فالشرط صحيح.':'8 ليست أقل من 5. جرّب المقارنة الثانية.';$('#demo-earned').classList.toggle('visible',correct);$('.demo-run').classList.toggle('finished',correct);$$('.demo-step .node').forEach((n,i)=>{n.className='node '+(correct?'done':i===2?'current':'done');n.innerHTML=correct?'✓':i===2?'3<i></i>':'✓'});$('#run-demo').innerHTML='<span>↻</span> شغّل مرة ثانية'};
}
function showTab(challenges){if(!$('#courses-page'))return;$('#courses-page').style.display=challenges?'none':'block';$('#challenge-page').style.display=challenges?'block':'none';$('#courses-tab').classList.toggle('active',!challenges);$('#challenges-tab').classList.toggle('active',challenges);$('#courses-tab').setAttribute('aria-selected',!challenges);$('#challenges-tab').setAttribute('aria-selected',challenges)}
if($('#courses-tab')){ $('#courses-tab').onclick=()=>showTab(false);$('#challenges-tab').onclick=()=>showTab(true);if(location.hash==='#challenges')showTab(true);
  $$('[data-field]').forEach(e=>e.onclick=()=>{if(e.dataset.field!=='python'){notice('المعاينة التفصيلية الحالية لمسار بايثون؛ بقية المسارات تتبع التكوين نفسه.');return}$$('[data-field]').forEach(b=>b.classList.toggle('active',b===e))});
  $('#learn-state').onchange=e=>{const n=e.target.value==='new';$('.current-course').classList.toggle('course-hidden',n);$$('.blank').forEach(e=>e.remove());if(n){const blank=document.createElement('div');blank.className='blank';blank.innerHTML='<span class="eyebrow">بداية المسار</span><h2>أساسيات Python</h2><p>تبدأ من الدرس الأول. دون شارات أو تقدم مفترض.</p><button class="btn primary" data-first>ابدأ أول درس</button>';$('.current-course').before(blank);blank.querySelector('button').onclick=()=>notice('هذه حالة عرض للحساب الجديد فقط.');$('.level-cut').textContent='1';}else $('.level-cut').textContent='3';};
  const changeState=$('#learn-state').onchange;
  $('#learn-state').onchange=e=>{changeState(e);const fresh=e.target.value==='new';$('.side-next').style.display=fresh?'none':'';if(fresh){$('.blank').innerHTML='<div class="chapter-index"><span class="node current">01<i></i></span><small>البداية</small></div><div class="chapter-header"><h3>أساسيات Python</h3><p>تبدأ من الدرس الأول. دون تقدم أو شارات مفترضة.</p><div class="chapter-meta">0 من 17 درسًا</div><button class="btn primary" style="margin-top:16px">ابدأ أول درس</button></div>';$('.blank button').onclick=()=>notice('هذه حالة عرض للحساب الجديد فقط.');}};
}
'''

for page, builder, title in [('welcome',welcome,'البداية'),('learn',learn,'التعلّم'),('rewards',rewards,'المكافآت')]:
    content = builder()
    if page == 'welcome':
        content = content.replace('فكرة تفهمها.<br><span>كود تكتبه.</span><br>خطوة تستحقها.', 'تعلّم البرمجة.<br><span>وشوف كودك يشتغل.</span>')
    if page == 'learn':
        content = content.replace('الشروط if/else <span class="tag now">الهدف التالي</span>', 'الآلة الحاسبة البسيطة <span class="tag now">قيد المحاولة</span>')
        content = content.replace('4 محلولة · الخطوة التالية من التحديات المتاحة', 'حالات عرض توضيحية من تحديات Python الموجودة')
        content = content.replace('تحدٍّ متاح</h3>', 'العدد الزوجي والفردي</h3>')
        content = content.replace('يُعرض العنوان والهدف من قائمة التحديات الحالية.', 'تحقق إذا كان العدد زوجيًا أم فرديًا.')
        content = content.replace('تحدٍّ محلول <span', 'تحدٍّ محلول — مثال حالة <span')
    if page == 'rewards':
        content = content.replace('1160 من 1600 XP', 'التقدم من المستوى 3 إلى 4، 1160 XP')
        content = content.replace('<span>1,160 XP</span>', '<span>900 XP</span>')
        content = content.replace('440 XP للمستوى الرابع', '1,160 XP · باقي 440 للمستوى الرابع')
    interaction = JS.replace("$('#run-demo').innerHTML='<span>↻</span> شغّل مرة ثانية'};", "$('#run-demo').innerHTML='<span>↻</span> شغّل مرة ثانية';if(correct)requestAnimationFrame(()=>$('#demo-earned').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}))};")
    refinements = '''
    .chapter-layout{grid-template-columns:minmax(0,620px)244px;justify-content:start}
    .lesson-track,.chapter-progress{max-width:470px}
    .current-lesson{max-width:470px}
    .achievement-copy{max-width:340px}
    .xp-line i{width:37.142857%}
    .demo-workbench:after{display:none}
    .blank{border:0;padding:0 0 25px;display:grid;grid-template-columns:68px minmax(0,1fr);gap:14px}
    .blank .chapter-index>.node{width:58px;height:58px;font-size:20px}
    .next-achievement{justify-content:center}
    @media(max-width:1000px){.chapter-layout{grid-template-columns:minmax(0,1fr)}.lesson-track,.chapter-progress{max-width:none}.current-lesson{max-width:none}}
    @media(max-width:720px){.hero-copy h1 br{display:block}.demo-code .code-lines{font-size:12px!important}.chapter-header,.lesson-info{min-width:0}.current-lesson .lesson-bottom{flex-wrap:wrap}.chapter-header .chapter-meta .btn{max-width:100%}.chapter-header .chapter-meta{gap:5px}}
    @media(max-width:720px){.blank{grid-template-columns:48px minmax(0,1fr);gap:11px}.blank .chapter-index>.node{width:42px;height:45px;font-size:16px}}
    @media(max-width:359px){.fields{margin-left:-12px;padding-left:12px}.lesson-line b{font-size:11px}.lesson-line .tag{font-size:8px}.demo-code .code-lines{font-size:10.5px!important}.hero-copy h1{font-size:27px}.blank{grid-template-columns:39px minmax(0,1fr);gap:8px}.blank .chapter-index>.node{width:34px;height:39px;font-size:13px}}
    '''
    html=f'<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kodax · معاينة {title} · اتجاه 02</title><style>{FONT}{CSS}{refinements}</style></head><body data-page="{page}">{review(page)}{content}{DIALOG}<script>{interaction}</script></body></html>'
    (OUT/f'kodax-{page}-v2.html').write_text(html,encoding='utf-8')
print('Saved three isolated responsive prototypes:',OUT)
